import re
songs_to_fill = []
for line in note_content.splitlines():
    if 'RELEASED_AT: TODO' in line:
        m = re.match(r'SONG: (.*?) \| ARTIST: (.*?) \| RELEASED_AT: TODO', line)
        if m:
            songs_to_fill.append({'title': m.group(1), 'artist': m.group(2)})
print(songs_to_fill)

